package org.icu.sepsis.notes;
import static org.junit.jupiter.api.Assertions.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.util.concurrent.atomic.AtomicReference;import org.junit.jupiter.api.Test;import com.sun.net.httpserver.HttpServer;import com.fasterxml.jackson.databind.ObjectMapper;
class BlbcjlClientTest {
 BlbcjlProperties props(int port){var p=new BlbcjlProperties();p.endpoint="http://127.0.0.1:"+port+"/notes";p.accessKey="synthetic-key-not-real";p.bqdm="SYNTHETIC-FIXED";p.mbkmc="synthetic-type";p.wjjgmc="synthetic-folder";return p;}
 @Test void postsExactProtocolWithFixedDepartmentAndNoName() throws Exception {var server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);AtomicReference<String> body=new AtomicReference<>(),method=new AtomicReference<>();server.createContext("/notes",exchange->{method.set(exchange.getRequestMethod());body.set(new String(exchange.getRequestBody().readAllBytes(),StandardCharsets.UTF_8));byte[] out="{\"code\":0,\"data\":[]}".getBytes(StandardCharsets.UTF_8);exchange.getResponseHeaders().set("Content-Type","application/json; charset=utf-8");exchange.sendResponseHeaders(200,out.length);exchange.getResponseBody().write(out);exchange.close();});server.start();try{var client=new BlbcjlClient(props(server.getAddress().getPort()));assertTrue(client.fetch("SYNTHETIC-STAY").length>0);var request=new ObjectMapper().readTree(body.get());assertEquals("POST",method.get());assertEquals("BLBCJL",request.path("method").asText());assertEquals("SYNTHETIC-STAY",request.path("data").path("BLH").asText());assertEquals("SYNTHETIC-FIXED",request.path("data").path("BQDM").asText());assertEquals(4,request.path("data").size());assertFalse(body.get().contains("HZXM"));}finally{server.stop(0);}}
 @Test void oversizedAndRedirectResponsesFailWithGenericErrors() throws Exception {var server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);server.createContext("/notes",exchange->{exchange.getRequestBody().readAllBytes();exchange.getResponseHeaders().set("Content-Type","application/json");exchange.sendResponseHeaders(200,2048);exchange.getResponseBody().write(new byte[2048]);exchange.close();});server.start();try{var p=props(server.getAddress().getPort());p.maxResponseBytes=1024;Exception e=assertThrows(java.io.IOException.class,()->new BlbcjlClient(p).fetch("SYNTHETIC-STAY"));assertFalse(e.getMessage().contains(p.accessKey));assertFalse(e.getMessage().contains(p.endpoint));}finally{server.stop(0);}}
 @Test void redirectsAreNotFollowedAndNonJsonIsRejected() throws Exception {var server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);var calls=new java.util.concurrent.atomic.AtomicInteger();server.createContext("/notes",exchange->{exchange.getRequestBody().readAllBytes();exchange.getResponseHeaders().set("Location","/target");exchange.sendResponseHeaders(302,-1);exchange.close();});server.createContext("/target",exchange->{calls.incrementAndGet();exchange.sendResponseHeaders(200,-1);exchange.close();});server.createContext("/html",exchange->{exchange.getRequestBody().readAllBytes();exchange.getResponseHeaders().set("Content-Type","text/html");exchange.sendResponseHeaders(200,-1);exchange.close();});server.start();try{var p=props(server.getAddress().getPort());assertThrows(java.io.IOException.class,()->new BlbcjlClient(p).fetch("SYNTHETIC"));assertEquals(0,calls.get());p.endpoint=p.endpoint.replace("/notes","/html");assertThrows(java.io.IOException.class,()->new BlbcjlClient(p).fetch("SYNTHETIC"));}finally{server.stop(0);}}
}
